<?php
namespace App\Http\Controllers;
use App\Models\{SalesInvoice,PurchaseInvoice,Customer,Supplier,Product}; use App\Services\InvoiceCalculator; use Illuminate\Http\Request; use Illuminate\Support\Str;
class InvoiceController extends Controller { public function index($type='sales'){ $model=$type==='purchase'?PurchaseInvoice::class:SalesInvoice::class; return view('invoices.index',['invoices'=>$model::with($type==='purchase'?'supplier':'customer')->latest()->paginate(15),'type'=>$type]); } public function show($type, $invoice){$model=$type==='purchase'?PurchaseInvoice::class:SalesInvoice::class; $invoice=$model::with(['items.product','payments',$type==='purchase'?'supplier':'customer'])->findOrFail($invoice);return view('invoices.show',compact('invoice','type'));} public function create($type='sales'){return view('invoices.form',['type'=>$type,'invoice'=>null,'parties'=>$type==='purchase'?Supplier::all():Customer::all(),'products'=>Product::all()]);} public function store(Request $request,InvoiceCalculator $calculator,$type='sales'){ $data=$request->validate(['party_id'=>'required|integer','issue_date'=>'required|date','due_date'=>'required|date','discount_value'=>'nullable|numeric|min:0','discount_type'=>'required|in:flat,percent','tax_rate'=>'nullable|numeric|min:0','items'=>'required|array|min:1','items.*.description'=>'required','items.*.quantity'=>'required|numeric|min:.01','items.*.unit_price'=>'required|numeric|min:0','items.*.tax_rate'=>'nullable|numeric|min:0']);$model=$type==='purchase'?PurchaseInvoice::class:SalesInvoice::class;$invoice=new $model;$invoice->fill(['invoice_number'=>strtoupper(Str::random(3)).'-'.now()->format('YmdHis'),'issue_date'=>$data['issue_date'],'due_date'=>$data['due_date'],'discount_value'=>$data['discount_value']??0,'discount_type'=>$data['discount_type'],'tax_rate'=>$data['tax_rate']??0,($type==='purchase'?'supplier_id':'customer_id')=>$data['party_id']]);$invoice->fill($calculator->calculate($invoice,$data['items']));$invoice->save();foreach($data['items'] as $item){$item['line_total']=bcmul((string)$item['quantity'],(string)$item['unit_price'],2);$invoice->items()->create($item);}return redirect()->route('invoices.show',[$type,$invoice]);} }
